pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;

    function setUp() public { c = new airDrop(); }

    function testFuzz_property(address from, uint256 v, uint8 _decimals) public {
        // The successful token: its transferFrom always succeeds, so the only
        // distinguishing observation is the boolean return value of c.transfer.
        SuccessToken tok = new SuccessToken();
        vm.assume(from != address(0));
        vm.assume(_decimals <= 77); // avoid 10**_decimals overflow for reasonable v
        vm.assume(v < type(uint256).max / (10 ** uint256(_decimals)) - 1);

        address[] memory tos = new address[](1);
        tos[0] = address(1);

        bool ok = c.transfer(from, address(tok), tos, v, _decimals);
        assertTrue(ok, "successful transfer must return true");
    }
}

contract SuccessToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    fallback() external {}
}
